import * as THREE from 'three';
import {buildInteriorDesign} from './interior-design.js?v=soft-sofa-9-release';
import {sourceFinish} from './catalogue-materials.js?v=soft-sofa-9-release';
function makePalette(design,kit){const palette={};for(const[key,p]of Object.entries(design.materials)){const physical=['glass','mirror','ceramic','linen','boucle','olive'].includes(key),mat=new THREE[physical?'MeshPhysicalMaterial':'MeshStandardMaterial']({name:'MT | '+key,color:p.color,roughness:p.roughness??.8,metalness:p.metalness??0,side:THREE.DoubleSide,envMapIntensity:.75});if(['linen','boucle','olive'].includes(key)){mat.sheen=.14;mat.sheenColor.set('#e9e0cd');mat.sheenRoughness=.9;}if(p.opacity){mat.transparent=true;mat.opacity=p.opacity;mat.depthWrite=false;}if(key==='glass'){mat.color.set('#c4d9d5');mat.roughness=.09;mat.metalness=.15;mat.envMapIntensity=1.35;mat.clearcoat=1;mat.clearcoatRoughness=.08;}if(key==='light'){mat.emissive.set(p.emissive);mat.emissiveIntensity=.3;}palette[key]=mat;}return kit.palette(palette,design.scheme);}
export async function loadNativeInterior(id,loadModel,kit){let disposed=false;const design=buildInteriorDesign(id),palette=makePalette(design,kit),gltf=await loadModel(`./assets/optimized/${id}.glb?v=soft-sofa-9-release`),root=gltf.scene,movable=[];root.name=design.title;
 root.traverse(o=>{if(o.userData.movable){o.userData.initial={x:o.position.x,z:o.position.z,rotation:o.rotation.y};movable.push(o);}if(!o.isMesh)return;let owner=o;while(owner&&!owner.userData.itemId)owner=owner.parent;const itemId=owner?.userData.itemId||'';if(/^(front|rear)-(glazing|door-)/.test(itemId))o.userData.blocksMovement=true;const list=Array.isArray(o.material)?o.material:[o.material];o.material=list.map(mat=>{let key=mat.name.replace('MT | ','');mat.dispose();return kit.roleMaterial(palette[key]||palette.limewash,id,itemId);});if(o.material.length===1)o.material=o.material[0];if(/pendant/.test(itemId)&&!['chalk'].includes(id)){const list=Array.isArray(o.material)?o.material:[o.material];o.material=list.map(m=>{if(m.name==='MT | cane'){const shade=m.clone();kit.apply(shade,id,'cane',{roughness:.96,normal:.22});shade.emissive.set('#d3ad77');shade.emissiveIntensity=.04;shade.userData.practicalShade=.1;return shade;}return m;});if(o.material.length===1)o.material=o.material[0];}
 o.castShadow=!(o.material.transparent||o.name.includes('glass'));o.receiveShadow=true;});
 return{design,root,palette,movable,scheme:id,dispose(){disposed=true;const mats=new Set(Object.values(palette));root.traverse(o=>{if(o.isMesh){o.geometry.dispose();for(const m of Array.isArray(o.material)?o.material:[o.material])mats.add(m);}});for(const mat of mats)mat.dispose();},async enhance(){await kit.ready();if(disposed)return;}};
}
function copyFinish(target,source){for(const key of ['map','normalMap','roughnessMap','bumpMap','roughness','metalness','envMapIntensity'])target[key]=source[key];target.color.copy(source.color);target.normalScale.copy(source.normalScale);target.needsUpdate=true;}
export function prepareShell(model,palette,kit,scheme){model.updateMatrixWorld(true);model.traverse(o=>{if(!o.isMesh)return;const positions=o.geometry.attributes.position,normals=o.geometry.attributes.normal,uv=new Float32Array(positions.count*2),v=new THREE.Vector3(),n=new THREE.Vector3(),nm=new THREE.Matrix3().getNormalMatrix(o.matrixWorld);for(let i=0;i<positions.count;i++){v.fromBufferAttribute(positions,i).applyMatrix4(o.matrixWorld);if(normals)n.fromBufferAttribute(normals,i).applyMatrix3(nm).normalize();else n.set(0,1,0);const ax=Math.abs(n.x),ay=Math.abs(n.y),az=Math.abs(n.z);uv[i*2]=(ay>=ax&&ay>=az?v.x:ax>=az?v.z:v.x)/1.5;uv[i*2+1]=(ay>=ax&&ay>=az?v.z:v.y)/1.5;}o.geometry.setAttribute('uv',new THREE.BufferAttribute(uv,2));const list=Array.isArray(o.material)?o.material:[o.material];o.material=list.map(m=>{const finish=sourceFinish(m.name);let next=m.clone();if(finish&&palette[finish]){next=palette[finish].clone();next.userData.sourceFinish=finish;}if(finish==='glass'){o.userData.blocksMovement=true;next.color.set('#e5ece7');next.map=null;next.opacity=.13;next.roughness=.14;next.metalness=.05;next.depthWrite=false;next.transparent=true;}if(finish==='chrome'){next.color.set('#b4bbb5');next.metalness=.92;next.roughness=.23;}next.name=m.name;next.side=THREE.DoubleSide;if(next.userData.catalogueFinish)kit.apply(next,scheme,next.userData.catalogueFinish,{tint:next.color.getHexString()==='ffffff'?'#ffffff':'#'+next.color.getHexString(),normal:next.normalScale.x,roughness:next.roughness});return next;});if(o.material.length===1)o.material=o.material[0];o.castShadow=!list.every(m=>m.transparent);o.receiveShadow=true;});}
export function styleShell(model,palette){model.traverse(o=>{if(!o.isMesh)return;for(const m of Array.isArray(o.material)?o.material:[o.material]){const finish=m.userData.sourceFinish;if(finish&&palette[finish])copyFinish(m,palette[finish]);}});}
export function addGarden(scene,palette){const root=new THREE.Group();root.name='Garden';const ground=new THREE.Mesh(new THREE.PlaneGeometry(100,100),new THREE.MeshStandardMaterial({color:'#a5a58a',roughness:1}));ground.rotation.x=-Math.PI/2;ground.position.set(-41,-.23,-5);ground.receiveShadow=true;root.add(ground);
 const leaf=new THREE.SphereGeometry(1,7,5);leaf.scale(.14,.62,.045);for(const [x,z]of[[-49,-5],[-49,-10],[-46,-12.4],[-41,-12.5],[-36,-12.3],[-34.7,-8],[-34.7,-3]])for(let j=0;j<7;j++){const a=j*2.4,m=new THREE.Mesh(leaf,j%2?palette.leaf:palette.leafLight);m.position.set(x+Math.sin(a)*.28,.7+(j%3)*.27,z+Math.cos(a)*.28);m.rotation.set(Math.sin(a)*.65,a,Math.cos(a)*.6);root.add(m);}
 const wall=new THREE.Mesh(new THREE.BoxGeometry(16,.65,.18),palette.limewash);wall.position.set(-41.7,.095,-13.1);wall.receiveShadow=true;root.add(wall);scene.add(root);return root;}
